<script lang="ts">
  const VALID_STATES = ['novo', 'bom', 'marcas_de_uso', 'danificado', 'manutencao', 'baixado'];
  let { onClose, onSaved }: { onClose: () => void; onSaved: (item: Record<string, unknown>) => void } = $props();
  let form = $state({ marca: '', modelo: '', modeloTecnico: '', numeroSerie: '', partNumber: '', pid: '', conexao: '', layout: '', estado: 'bom', observacoes: '' }); let erro = $state(''); let salvando = $state(false);
  async function salvar() { if (!form.marca.trim() || !form.modelo.trim() || !form.modeloTecnico.trim() || !form.partNumber.trim() || !form.conexao.trim() || !form.layout.trim()) { erro = 'Preencha os campos obrigatórios.'; return; } salvando = true; try { const response = await fetch('/api/equipamentos/teclado', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (response.status === 401) { window.location.assign('/login'); return; } if (!response.ok) { erro = 'Não foi possível cadastrar o teclado.'; return; } onSaved(await response.json()); } catch { erro = 'Não foi possível cadastrar o teclado. Tente novamente.'; } finally { salvando = false; } }
</script>
<div class="modal edit-person-modal" role="presentation" onclick={(event) => event.target === event.currentTarget && !salvando && onClose()}><div class="modal__content edit-person-dialog card panel" role="dialog" aria-modal="true" aria-labelledby="keyboard-title"><div class="edit-person-heading"><h2 id="keyboard-title">Adicionar teclado</h2><button class="button--secondary edit-person-close" type="button" onclick={onClose}>×</button></div><form onsubmit={(event) => { event.preventDefault(); salvar(); }}><div class="form-grid">{#each [['marca','Marca'],['modelo','Modelo'],['modeloTecnico','Modelo técnico'],['numeroSerie','Número de série'],['partNumber','Part number'],['pid','PID'],['conexao','Conexão'],['layout','Layout']] as field}<div class="form-group"><label for={`keyboard-${field[0]}`}>{field[1]}</label><input id={`keyboard-${field[0]}`} bind:value={form[field[0] as keyof typeof form]} /></div>{/each}<div class="form-group"><label for="keyboard-estado">Estado</label><select id="keyboard-estado" bind:value={form.estado}>{#each VALID_STATES as state}<option value={state}>{state}</option>{/each}</select></div><div class="form-group"><label for="keyboard-observacoes">Observações</label><textarea id="keyboard-observacoes" bind:value={form.observacoes}></textarea></div></div>{#if erro}<p class="form-error" role="alert">{erro}</p>{/if}<footer class="form-actions edit-person-actions"><button class="button--secondary" type="button" onclick={onClose}>Cancelar</button><button class="button--primary" type="submit" disabled={salvando}>Salvar</button></footer></form></div></div>
